import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"LIVE 接続を管理する","description":"","frontmatter":{"title":"LIVE 接続を管理する","docId":"user.live.connections","translationKey":"user.live.connections","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","translationRevision":"c7753dbf5f8630bf5fbaec65d02370c405f5e7e33d34b3583d935a7e312bb4d2","order":10},"headers":[],"relativePath":"ja/user/live/connections.md","filePath":"ja/user/live/connections.md","lastUpdated":1795731074000}`),s={name:`ja/user/live/connections.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="manage-live-connections" tabindex="-1">LIVE 接続を管理する <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to “LIVE 接続を管理する”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>特定の配信者への接続と再接続を理解し、プラグインサーバーを独立して設定します。正常な<a href="./../installation.html">デスクトップ環境</a>、ネットワーク、配信者のハンドルが必要です。OS の問題を診断する前に<a href="./../requirements.html">動作要件</a> を確認します。</p><h2 id="connect-deliberately" tabindex="-1">接続内容を確認して操作する <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to “接続内容を確認して操作する”">​</a></h2><ol><li><strong>接続</strong> でハンドルを入力します。<code>@</code> の有無は問いません。表示名とは異なる識別子です。</li><li><strong>セッションCookieを使用</strong> を無効にして始めます。TikTok が許可済みセッションを求めたら有効にし、マスク欄だけに Cookie を入力します。Cookie はメモリー内に留まります。診断や Cloud 設定に貼り付けないでください。</li><li>直接試す場合は <strong>監視して自動接続</strong> を無効にして <strong>接続</strong> を選びます。再試行前に状態とエラーを読みます。</li><li><a href="./feed.html">ライブフィード</a> で正しい配信者と新しいイベントを確認します。接続済みでも静かなルームなら動きがない場合があります。</li><li>同じ配信者には <strong>再接続</strong>、配信者を変える前には <strong>切断</strong> を使います。処理中の試行は <strong>キャンセル</strong> で止めます。</li></ol><p>直接接続に成功した後、監視を有効にして配信開始を待てます。待機・確認中は接続済みとは異なります。固定されたハンドルの編集前に監視を停止します。最近の配信者を選ぶ操作は、入力を埋めるだけでなく接続も開始します。</p><p>エクスプローラーには検出したルームが表示されますが、古くなることがあります。利用可能と判断する前に更新してください。下部パネルのプラグインサーバー接続は各サービスの設定で、プラグイン接続済みでも TikTok や Cloud の認証にはなりません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “期待される結果と提供状況”">​</a></h2><p>直接接続、監視、プラグイン接続の操作を利用できます。同じ配信者への再接続はフィードの対象を保持し、配信者の変更は対象を切り替えます。実際の TikTok アクセスは配信元のルームとセッションに依存し、ローカルテストの成功では保証されません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to “問題が起きたとき”">​</a></h2><p>オフラインのルームでは配信中か確認します。セッションやレート制限のエラーでは示された再試行条件に従います。再接続の連打では認証は更新されません。<a href="./../preferences/troubleshooting.html">トラブルシューティング</a> に従い、認証情報を出さずに失敗した要素と時刻を記録します。</p><p>実際の設定に触れる前にインタラクティブに試せます:</p>`,12),t(d,{scenario:`connection`,locale:`ja`,panel:`connection`,title:`LIVE接続パネルを試す`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>ライブルームに接続</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>ライブルームを対話的に選択</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>ライブチャンネルを発見；セッションなしで動作</td></tr><tr><td><code>tiktools live disconnect</code></td><td>現在のルームから切断 <strong>破壊的</strong></td></tr><tr><td><code>tiktools live status</code></td><td>現在の接続状態</td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};